<tr><td>2</td><td><strong>Robert Henry Rycroft Sr.</strong></td><td>27 Apr 1843</td><td>3 Feb 1909</td><td>Leeds → U.S. (Civil War) → Honolulu &amp; Puna, Hawai&rsquo;i</td><td><strong>Verified</strong> &mdash; Hawaiian newspapers / 1909 obituary; <em>Images of Old Hawaii</em></td></tr>
<tr><td>2</td><td><strong>Elizabeth P. (Campbell) Rycroft</strong> <em>(wife)</em></td><td>c. 1850</td><td>after 1909</td><td>Hawai&rsquo;i</td><td><strong>Verified</strong> (relationship) &mdash; sister of A.N. Campbell, Hawai&rsquo;i Treasurer (1909 obituary)</td></tr>
